import React, { useState, useEffect, useRef } from 'react'
import { chat } from './api'

// Import icons for better UI
import { Send, Sparkles, Bot, User } from 'lucide-react'

// Import avatars
import botIcon from './images/bot.png'
import userIcon from './images/user.png'

// Example prompts for welcome message
const EXAMPLE_PROMPTS = [
  'Show milk products',
  'What\'s best for a 2 year old?',
  'Which has the most protein?',
  'Show me Lato snacks',
  'Compare toddler formulas'
]

export default function App() {
  const [sessionId, setSessionId] = useState(null)
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [suggestions, setSuggestions] = useState([])
  const [loading, setLoading] = useState(false)
  const [showWelcome, setShowWelcome] = useState(true)
  const chatRef = useRef(null)

  // Auto-scroll to bottom
  useEffect(() => {
    if (chatRef.current) {
      chatRef.current.scrollTop = chatRef.current.scrollHeight
    }
  }, [messages, loading])

  // Initial greeting
  useEffect(() => {
    if (sessionId === null) {
      (async () => {
        try {
          setLoading(true)
          const res = await chat(null, 'hi')
          setSessionId(res.session_id)
          addBotMessage(res.reply, null, true) // isWelcomeMessage flag
        } catch (err) {
          addBotMessage('Hello! I\'m Lato, your nutrition buddy. Let\'s talk about healthy options for your family!', null, true)
        } finally {
          setLoading(false)
        }
      })()
    }
  }, [])

  function addUserMessage(txt) {
    setMessages(m => [...m, { role: 'user', text: txt }])
    setShowWelcome(false)
  }

  function addBotMessage(txt, product = null, isWelcomeMessage = false) {
    setMessages(m => [...m, { role: 'bot', text: txt, product, isWelcomeMessage }])
  }

  async function handleSend(msgText = null) {
    const msg = msgText || input.trim()
    if (!msg) return

    addUserMessage(msg)
    setInput('')
    setLoading(true)
    setShowWelcome(false)

    try {
      const res = await chat(sessionId, msg)
      setSessionId(res.session_id)
      addBotMessage(res.reply, res.product)
      setSuggestions(res.suggestions || EXAMPLE_PROMPTS.slice(0, 3))
    } catch {
      addBotMessage('Hmm, I\'m having trouble connecting. Can you try that again? In the meantime, you can ask about:')
      setSuggestions(EXAMPLE_PROMPTS.slice(0, 3))
    } finally {
      setLoading(false)
    }
  }

  // Format message text with better line handling
  const formatMessage = (text) => {
    return text.split('\n').map((line, idx) => (
      <div key={idx} style={{ marginBottom: line ? '4px' : '0' }}>
        {line || <br />}
      </div>
    ))
  }

  return (
    <div className="app">
      <div className="header">
        <Bot size={28} color="#004c97" />
        <h2>Lato Nutrition Buddy</h2>
        <span className="statusBadge">Online</span>
      </div>

      {showWelcome && (
        <div className="welcomeMessage">
          <h3>👋 Hi, I'm Lato!</h3>
          <p>I can help you explore products, check nutrition, or recommend options for children.</p>
          <div className="examplePrompts">
            {EXAMPLE_PROMPTS.map((prompt, idx) => (
              <button 
                key={idx} 
                onClick={() => handleSend(prompt)}
                disabled={loading}
              >
                {prompt}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="chatbox" ref={chatRef}>
        {messages.map((m, i) => (
          <div
            key={i}
            className={`messageRow ${m.role === 'user' ? 'userRow' : 'botRow'}`}
          >
            {m.role === 'bot' && (
              <div className="avatarWrapper">
                <img
                  className="avatar"
                  src={botIcon}
                  alt="Lato Assistant"
                />
                {i === 0 && <div className="onlineDot"></div>}
              </div>
            )}

            <div className={`bubble ${m.role}`}>
              {m.isWelcomeMessage ? (
                <>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '12px' }}>
                    <Sparkles size={18} color="#004c97" />
                    <strong>Hi — I'm Lato, your friendly nutrition buddy!</strong>
                  </div>
                  <p>I can help you explore products, check nutrition, or recommend options for children.</p>
                  <p style={{ marginTop: '12px', fontSize: '0.9rem', color: '#475569' }}>
                    Try asking: <em>"show milk"</em>, <em>"what's best for a 2 year old"</em>, <em>"which has the most protein"</em>, or ask for a product by name.
                  </p>
                </>
              ) : formatMessage(m.text)}

              {m.product && (
                <div
                  className="productCard"
                  onClick={() => handleSend(`Tell me more about ${m.product.name}`)}
                  title="Click for more details"
                >
                  {m.product.image && (
                    <img src={m.product.image} alt={m.product.name} />
                  )}
                  <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <strong>{m.product.name}</strong>
                      {m.product.age_range && (
                        <span className="ageBadge">
                          {m.product.age_range.join('+')}
                        </span>
                      )}
                    </div>
                    <div style={{ fontSize: '0.9rem', color: '#64748b' }}>
                      SKU: {m.product.sku}
                    </div>
                    {m.product.description && (
                      <div style={{ marginTop: '8px', fontSize: '0.9rem' }}>
                        {m.product.description}
                      </div>
                    )}
                    <div style={{ marginTop: '8px', fontSize: '0.85rem', color: '#004c97' }}>
                      <strong>Click for nutrition details →</strong>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {m.role === 'user' && (
              <div className="avatarWrapper">
                <img
                  className="avatar userAvatar"
                  src={userIcon}
                  alt="You"
                />
              </div>
            )}
          </div>
        ))}

        {loading && (
          <div className="messageRow botRow">
            <div className="avatarWrapper">
              <img className="avatar" src={botIcon} alt="bot" />
            </div>
            <div className="bubble bot typing">
              Thinking...
            </div>
          </div>
        )}
      </div>

      {suggestions.length > 0 && !loading && (
        <div className="suggestionBox">
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
            <Sparkles size={16} color="#004c97" />
            <strong>Try asking:</strong>
          </div>
          <div className="suggestionButtons">
            {suggestions.map((s, idx) => (
              <button 
                key={idx} 
                onClick={() => handleSend(s)}
                disabled={loading}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="inputRow">
        <input
          type="text"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleSend()}
          placeholder="Ask about products, nutrition, or recommendations..."
          disabled={loading}
        />
        <button 
          className="sendButton" 
          onClick={() => handleSend()}
          disabled={loading || !input.trim()}
        >
          <Send size={20} />
          Send
        </button>
      </div>
    </div>
  )
}
